.picker-restore { margin-top: 12px; padding: 12px 18px; border: 1px solid var(--line); border-radius: 999px; background: transparent; color: var(--text); cursor: pointer; }

/* Full-screen player (opened by tapping the cover). */

/* Diagnostics panel (long press on the clock). */
.diag-sheet { width: min(1100px, 100%); }
.diag-log { margin: 0 0 14px; max-height: 32vh; overflow: auto; padding: 12px; border-radius: 14px; background: var(--surface-soft); color: var(--text); font: 12px/1.45 ui-monospace, Consolas, monospace; white-space: pre-wrap; word-break: break-all; }
.diag-tests { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
