.diag-group { width: 100%; margin-top: 8px; font-weight: 700; color: var(--muted); }

/* Tiggo 9 home (separate layout, switched on in the diagnostics panel). */
.go-home { width: 56px; height: 56px; border: 1px solid var(--line); border-radius: 50%; background: var(--surface-soft); color: var(--text); font-size: 26px; cursor: pointer; }
.go-home[hidden] { display: none; }
body.tg-on .dashboard, body.tg-on .actions-section { display: none; }
.tg-home { display: none; position: fixed; inset: 0; z-index: 5; grid-template-columns: 110px 1fr; gap: 14px; grid-template-rows: minmax(0, 1fr); padding: 14px; background: var(--hero-image), var(--bg); color: var(--text); }
body.tg-on .tg-home { display: grid; }
.tg-side { min-height: 0; display: flex; flex-direction: column; gap: 8px; padding: 10px 6px; border-radius: 24px; background: var(--surface); border: 1px solid var(--line); }
.tg-side button { display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 10px 4px; border: 0; border-radius: 16px; background: transparent; color: var(--muted); font-size: 12px; cursor: pointer; }
.tg-side button.active, .tg-side button:hover { color: var(--text); background: var(--surface-soft); }
.tg-ico { width: 28px; height: 28px; display: grid; place-items: center; }
.tg-ico svg { width: 28px; height: 28px; }
.tg-grid { display: grid; grid-template-columns: 1fr 1fr 1fr 1fr; grid-template-rows: minmax(0, 1.05fr) minmax(0, 1fr); gap: 14px; min-width: 0; min-height: 0; }
.tg-card { min-width: 0; min-height: 0; padding: 16px; border-radius: 33px; background: rgba(2, 6, 12, .94); backdrop-filter: blur(22px); box-shadow: 0 18px 50px rgba(0, 0, 0, .28); border: 1px solid rgba(255, 255, 255, .16); display: flex; flex-direction: column; overflow: hidden; }
.tg-card h4 { margin: 0 0 8px; font-size: 14px; font-weight: 600; color: var(--muted); }
.tg-hero { grid-row: 1; grid-column: 1 / span 3; position: relative; border-radius: 33px; overflow: hidden; background: linear-gradient(180deg, rgba(8, 10, 14, .7) 0%, rgba(8, 10, 14, .25) 40%, rgba(8, 10, 14, .55) 100%), url("images/tiggo/bg-mountains.jpg") center / cover no-repeat, rgba(2, 6, 12, .94); backdrop-filter: blur(22px); box-shadow: 0 18px 50px rgba(0, 0, 0, .28); border: 1px solid rgba(255, 255, 255, .16); }
.tg-car { position: absolute; left: 50%; top: 38px; transform: translateX(-50%); width: 58%; max-height: 46%; object-fit: contain; }
.tg-clock { position: absolute; left: 22px; top: 16px; }
.tg-clock strong { display: block; font-size: 64px; font-weight: 300; line-height: 1; }
.tg-clock span { color: var(--muted); font-size: 16px; }
.tg-weather { position: absolute; right: 22px; top: 18px; text-align: right; }
.tg-weather span { display: block; color: var(--muted); font-size: 14px; }
.tg-weather strong { font-size: 40px; font-weight: 300; }
.tg-side-stack { grid-row: 2; grid-column: 4; min-height: 0; min-width: 0; display: flex; flex-direction: column; gap: 14px; }
.tg-side-stack .tg-music { flex: 1.15 1 0; min-height: 0; justify-content: space-between; gap: 10px; }
.tg-side-stack .tg-apps-card { flex: 1 1 0; min-height: 0; }
.tg-side-stack .tg-art { display: none; }
.tg-side-stack .tg-controls button { width: 50px; height: 50px; font-size: 20px; }
.tg-side-stack .tg-track strong { font-size: 22px; }
.tg-top { display: flex; align-items: center; gap: 14px; min-width: 0; }
.tg-art { flex: 0 0 auto; width: 110px; height: 110px; border-radius: 22px; background: var(--surface-soft) center / cover no-repeat; display: grid; place-items: center; font-size: 46px; color: var(--muted); }
.tg-art.has-image span { display: none; }
.tg-track { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.tg-track strong { font-size: 20px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tg-track span { color: var(--muted); font-size: 15px; }
.tg-eyebrow { font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
.tg-controls { display: flex; flex-direction: row; justify-content: center; gap: 12px; }
.tg-controls button { width: 60px; height: 60px; border: 0; border-radius: 50%; background: var(--surface-soft); color: var(--text); font-size: 24px; cursor: pointer; }
.tg-car-card { grid-row: 2; grid-column: 2; align-items: center; }
.tg-nav { grid-row: 1; grid-column: 4; cursor: pointer; }
.tg-nav-map { position: relative; overflow: hidden; flex: 1; border-radius: 16px; background: repeating-linear-gradient(90deg, rgba(var(--accent-rgb), .10) 0 2px, transparent 2px 36px), repeating-linear-gradient(0deg, rgba(var(--accent-rgb), .10) 0 2px, transparent 2px 36px), var(--surface-soft); display: grid; place-items: center; font-size: 64px; color: var(--accent); }
.tg-nav-foot { position: absolute; left: 10px; right: 10px; bottom: 10px; height: 44px; z-index: 2; border: 0; padding: 0 14px; border-radius: 14px; background: rgba(17, 17, 20, .84); color: var(--text); font: inherit; display: flex; justify-content: space-between; align-items: center; cursor: pointer; text-align: left; }
.tg-nav-foot span { font-size: 26px; color: var(--muted); }
.tg-nav-foot strong { font-size: 16px; }
.tg-car-card img { flex: 1; min-height: 0; width: 100%; object-fit: contain; }
.tg-car-info { font-size: 12px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.tg-quick { grid-row: 2; grid-column: 3; display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: auto minmax(0, 1fr) minmax(0, 1fr); gap: 10px; }
.tg-quick h4 { grid-column: 1 / span 2; }
.tg-quick button { min-height: 0; display: flex; flex-direction: column; align-items: flex-start; justify-content: space-between; padding: 10px; border: 1px solid var(--line); border-radius: 26px; background: rgba(11, 22, 39, .92); color: var(--text); font-size: 14px; text-align: left; cursor: pointer; }
.tg-quick button .tg-ico { width: 30px; height: 30px; }
.tg-quick button .tg-ico svg { width: 30px; height: 30px; }
.tg-data-card { grid-row: 2; grid-column: 1; }
.tg-apps { flex: 1; display: grid; grid-template-columns: 1fr 1fr; gap: 10px; min-height: 0; }
.tg-app { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; border: 1px solid var(--line); border-radius: 18px; background: var(--surface-soft); color: var(--text); font-size: 13px; cursor: pointer; padding: 8px; min-width: 0; }
.tg-app:disabled { color: var(--muted); cursor: default; }
.tg-app-icon { width: 44px; height: 44px; border-radius: 14px; display: grid; place-items: center; background: rgba(var(--accent-rgb), .16); color: var(--accent); font-size: 20px; font-weight: 700; }

.tg-drive { position: absolute; left: 22px; top: 124px; display: flex; gap: 26px; }
.tg-drive strong { display: block; font-size: 44px; font-weight: 300; line-height: 1; }
.tg-drive span { color: var(--muted); font-size: 14px; }

/* Car animation: a small strip at the top with the car thumbnail and the part that opens or closes. */
.car-anim { position: fixed; top: max(12px, env(safe-area-inset-top, 0px)); left: 50%; transform: translateX(-50%); z-index: 36; width: min(560px, calc(100vw - 32px)); display: flex; align-items: center; gap: 14px; padding: 10px 18px 10px 10px; border-radius: 23px; background: rgba(2, 6, 12, .94); border: 1px solid rgba(255, 255, 255, .14); color: #eaf2ff; box-shadow: 0 10px 30px rgba(0, 0, 0, .35); pointer-events: none; }
.car-anim[hidden] { display: none; }
.car-anim.show { animation: caDrop .3s ease-out; }
@keyframes caDrop { from { opacity: 0; transform: translate(-50%, -24px); } to { opacity: 1; transform: translate(-50%, 0); } }
.car-anim-box { position: relative; flex: 0 0 auto; width: min(180px, 34vw); aspect-ratio: 900 / 287; }
.car-anim-box img { width: 100%; height: 100%; object-fit: contain; display: block; }
.car-anim-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.ca-part { display: none; }
.ca-part.on { display: inline; }
.ca-hole { fill: #02060c; opacity: .9; }
.ca-lid { fill: rgba(190, 205, 220, .28); stroke: var(--accent); stroke-width: 12; }
.ca-glass { fill: rgba(var(--accent-rgb), .30); stroke: var(--accent); stroke-width: 12; }
.ca-part.on .ca-lid { transform-box: fill-box; }
.ca-part[data-kind="trunk"] .ca-lid { transform-origin: left center; }
.ca-part[data-kind="roof"] .ca-lid { animation: caRoof var(--ca-dur, 1.6s) ease-in-out both; }
.ca-part[data-kind="trunk"] .ca-lid { animation: caTrunk var(--ca-dur, 1.6s) ease-in-out both; }
.ca-part[data-kind="windows"] .ca-glass { transform-box: fill-box; transform-origin: center; animation: caWin var(--ca-dur, 1.6s) ease-in-out both; }
.ca-part.closing .ca-lid, .ca-part.closing .ca-glass { animation-direction: reverse; }
@keyframes caTrunk { 0% { transform: scaleX(1); } 45%, 100% { transform: scaleX(.3); } }
@keyframes caRoof { 0% { transform: translateX(0); } 45%, 100% { transform: translateX(90px); } }
@keyframes caWin { 0% { transform: scaleY(1); } 45%, 100% { transform: scaleY(.2); } }
.car-anim-text { min-width: 0; font-size: 20px; font-weight: 600; line-height: 1.2; color: inherit; }
:root[data-theme="light"] .car-anim { background: rgba(255, 255, 255, .95); border-color: rgba(31, 116, 184, .25); color: #13243a; }

#tg-map-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.tg-nav-turn { position: absolute; left: 10px; right: 10px; top: 10px; display: flex; align-items: center; gap: 12px; padding: 10px 12px; border-radius: 16px; background: rgba(17, 17, 20, .84); color: var(--text); }
.tg-nav-turn b { font-size: 34px; line-height: 1; color: var(--accent); min-width: 36px; text-align: center; }
.tg-nav-turn > span { display: flex; flex-direction: column; min-width: 0; }
.tg-nav-turn strong { font-size: 22px; }
.tg-nav-turn small { font-size: 15px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.tg-data-card { display: flex; flex-direction: column; }
.tg-data { flex: 1; min-height: 0; display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1.3fr 1fr 1fr; gap: 10px; margin-top: 10px; }
.tg-tile { min-width: 0; min-height: 0; padding: 8px 10px; overflow: hidden; border-radius: 18px; border: 1px solid var(--line); background: rgba(11, 22, 39, .92); display: flex; flex-direction: column; justify-content: space-between; }
.tg-tile-wide { grid-column: 1 / span 2; }
.tg-tile > span { color: var(--muted); font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tg-tile p { margin: 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 5px; min-width: 0; }
.tg-tile strong { font-size: 26px; font-weight: 600; line-height: 1; color: var(--text); white-space: nowrap; }
.tg-tile em { font-style: normal; color: var(--muted); font-size: 13px; white-space: nowrap; }
.tg-tile-wide strong { font-size: 42px; }

.tg-apps-card { display: flex; flex-direction: column; }
.tg-side-stack .tg-apps-card { padding: 12px; }
.tg-side-stack .tg-apps-card h4 { margin-bottom: 4px; }
.tg-side-stack .tg-apps { grid-auto-rows: minmax(0, 1fr); }
.tg-side-stack .tg-apps > * { min-height: 0; overflow: hidden; }

.tg-car-wrap { position: relative; flex: 1; min-height: 0; width: 100%; }
.tg-car-wrap img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; }
.tg-tyre { position: absolute; display: flex; flex-direction: column; align-items: flex-start; padding: 5px 9px; border-radius: 12px; border: 1px solid var(--line); background: rgba(11, 22, 39, .92); font-weight: 600; font-size: 15px; line-height: 1.15; white-space: nowrap; }
.tg-tyre small { color: var(--muted); font-size: 12px; font-weight: 400; }
.tg-tyre.fl { left: 0; top: 4%; }
.tg-tyre.fr { right: 0; top: 4%; align-items: flex-end; }
.tg-tyre.rl { left: 0; bottom: 4%; }
.tg-tyre.rr { right: 0; bottom: 4%; align-items: flex-end; }

.tg-car-states { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.tg-st { fill: transparent; stroke: transparent; stroke-width: 4; }
.tg-st.on { fill: rgba(var(--accent-rgb), .28); stroke: var(--accent); }

/* Tiggo layout with a classic page inside: the slots fill the area to the right of the sidebar. */
body.tg-on.tg-section .dashboard { display: block; position: fixed; left: 150px; top: 14px; right: 14px; bottom: 14px; z-index: 6; min-height: 0; padding: 0; margin: 0; width: auto; background: transparent; }
body.tg-on.tg-section .dashboard > .hero { display: none; }
body.tg-on.tg-section .actions-section { display: block; height: 100%; overflow: auto; }
body.tg-on.tg-section .tg-grid { display: none; }
body.tg-on.tg-section .action-slots { grid-auto-flow: row; grid-auto-columns: auto; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); justify-content: stretch; overflow: visible; padding: 4px 2px 10px; }
body.tg-on.tg-section .action-slots > * { min-height: 171px; }
/* The sidebar already lists these pages, so the tab row is hidden in the Tiggo layout. */
body.tg-on.tg-section .page-tabs { display: none; }
.tg-side button[hidden] { display: none; }
.tg-nav-radar { position: absolute; left: 10px; bottom: 10px; display: flex; flex-direction: column; padding: 6px 10px; border-radius: 12px; background: rgba(17, 17, 20, .84); border: 1px solid var(--line); }
