/* Медиаплеер под машиной, внутри большой карточки */
.tg-hero .tg-music-hero { position: absolute; left: 0; right: 0; bottom: 0; background: rgba(2, 6, 12, .94); border-radius: 22px 22px 33px 33px; padding: 14px 24px; flex-direction: row; align-items: center; gap: 14px; }
.tg-hero .tg-music-hero .tg-top { flex: 1; min-width: 0; }
.tg-hero .tg-music-hero .tg-art { width: 72px; height: 72px; border-radius: 16px; }
.tg-hero .tg-music-hero .tg-controls { flex: 0 0 auto; }

/* Состояние автомобиля в правой карточке: только известные значения */
.tg-state-list { list-style: none; margin: 4px 0 8px; padding: 0; display: grid; gap: 6px; }
.tg-state-list[hidden] { display: none; }
.tg-state-list li { display: flex; justify-content: space-between; align-items: center; padding: 8px 12px; border-radius: 14px; background: var(--surface-soft); border: 1px solid var(--line); font-size: 15px; }
.tg-state-list span { color: var(--muted); }
.tg-state-list b { font-weight: 600; color: var(--muted); }
.tg-state-list li.open { border-color: var(--accent); }
.tg-state-list li.open b { color: var(--accent); }
.tg-side-stack .tg-state-list + .tg-apps { flex: 1 1 auto; }
