.temp-pill .tp-val { font-size: 26px; font-weight: 700; font-variant-numeric: tabular-nums; }
.temp-pill .tp-bar { position: relative; width: 6px; height: 120px; border-radius: 3px; background: #ffffff22; overflow: hidden; }
.temp-pill .tp-bar i { position: absolute; left: 0; right: 0; bottom: 0; background: var(--accent); }
:root[data-theme="light"] .temp-pill { background: #fffffff5; color: #1b2640; border-color: #d5dbe5; box-shadow: 0 14px 40px rgba(0, 0, 0, .18); }
:root[data-theme="light"] .temp-pill .tp-who { color: #5f6f88; }
:root[data-theme="light"] .temp-pill .tp-arr { color: #2f6fd1; }
:root[data-theme="light"] .temp-pill .tp-bar { background: #d5dbe5; }
:root[data-theme="light"] .temp-pill .tp-bar i { background: #2f6fd1; }

/* Карточка вентилятора: значение 1–10 и ряд из 10 нажимаемых сегментов с номерами. */
.hw-fan-value { font-size: 44px; font-weight: 700; text-align: center; font-variant-numeric: tabular-nums; margin-top: 4px; }
.hw-fan-bar { display: flex; gap: 3px; margin-top: auto; }
.hw-fan-bar i { flex: 1; height: 26px; border-radius: 6px; background: #ffffff1c; color: #8aa0bd; font: 600 10px system-ui, sans-serif; font-style: normal; display: grid; place-items: center; cursor: pointer; }
.hw-fan-bar i.on { background: var(--accent); color: #0b1622; }
:root[data-theme="light"] .hw-fan-bar i { background: #d5dbe5; color: #5f6f88; }
:root[data-theme="light"] .hw-fan-bar i.on { background: #2f6fd1; color: #ffffff; }
.hw-card.hw-fan { padding: 14px 10px; }
.hw-fan-bar { gap: 2px; }
.hw-fan-bar i { font-size: 9px; border-radius: 5px; height: 28px; }
.hw-state .hw-body { margin-top: 22px; }
.hw-state .hw-body { margin-top: 16px; }
.hw-state .hw-chips { gap: 6px; }
.hw-state .hw-chip { min-height: 34px; padding: 5px 12px; }

/* Окно настроек в светлой теме. */
:root[data-theme="light"] .set-card { background: #f5f6f8; color: #1b2640; border-color: #d5dbe5; box-shadow: 0 16px 50px rgba(27, 38, 64, .18); }
:root[data-theme="light"] .set-head h2 { color: #1b2640; }
:root[data-theme="light"] .set-close { background: #ffffff; color: #1b2640; border: 1px solid #d5dbe5; }
:root[data-theme="light"] .set-tabs button { background: #ffffff; color: #5f6f88; border-color: #d5dbe5; }
:root[data-theme="light"] .set-tabs button.active { background: rgba(47, 111, 209, .12); color: #1b2640; border-color: #2f6fd1; }
:root[data-theme="light"] .set-body button { background: #ffffff; color: #1b2640; border-color: #d5dbe5; }
:root[data-theme="light"] .set-body button.on { background: #d9e9fd; color: #202e40; border-color: #2f6fd1; }
:root[data-theme="light"] .set-note { color: #5f6f88; }
:root[data-theme="light"] .set-switch b { color: #5f6f88; }
:root[data-theme="light"] .set-fav { background: #ffffff; color: #1b2640; border: 1px solid #d5dbe5; }
/* Развёрнутый плеер: часы и погода той же высоты, что и плеер. */
body.player-expanded .hero-bottom.in-stage > .hero-clock, body.player-expanded .hero-bottom.in-stage > #weather-widget { align-self: stretch; height: auto !important; min-height: 0 !important; }

/* Night mode: only the big clock on a black screen. Entered by a tap on the classic clock, left by any tap. */
body.night-mode { background: #05070c !important; }
body.night-mode::before, body.night-mode::after,
body.night-mode #hero::before, body.night-mode #hero::after,
body.night-mode .dashboard::before, body.night-mode .dashboard::after,
body.night-mode .hero-shade { display: none !important; }
body.night-mode .dashboard { background: #05070c !important; background-image: none !important; }
body.night-mode #hero { position: fixed !important; inset: 0 !important; background: #05070c !important; background-image: none !important; }
body.night-mode #hero > *:not(.hero-bottom) { display: none !important; }
body.night-mode .dashboard > *:not(#hero) { display: none !important; }
body.night-mode .hero-bottom { position: fixed !important; inset: 0 !important; display: flex !important; align-items: center !important; justify-content: center !important; height: auto !important; }
body.night-mode .hero-bottom > *:not(.hero-clock) { display: none !important; }
body.night-mode .hero-clock { background: transparent !important; border: 0 !important; box-shadow: none !important; min-height: 0 !important; height: auto !important; width: auto !important; flex: none !important; padding: 0 !important; animation: nightIn .6s ease-out both; }
body.night-mode .hero-clock .clock { font-size: clamp(120px, 26vw, 260px) !important; font-weight: 200 !important; color: rgba(200, 210, 225, .78) !important; text-shadow: 0 0 40px rgba(200, 210, 225, .25); line-height: 1 !important; font-variant-numeric: tabular-nums; }
body.night-mode .toast, body.night-mode .car-anim { display: none !important; }
@keyframes nightIn { from { opacity: 0; transform: scale(.92); } to { opacity: 1; transform: scale(1); } }
.night-hint { position: fixed; bottom: 12%; left: 50%; transform: translateX(-50%) translateY(8px); z-index: 101; padding: 9px 20px; border-radius: 999px; background: rgba(255, 255, 255, .06); border: 1px solid rgba(255, 255, 255, .1); color: rgba(220, 225, 235, .6); font-size: 13px; letter-spacing: .04em; white-space: nowrap; pointer-events: none; opacity: 0; display: none; }
body.night-mode .night-hint { display: block; }
.night-hint.show { animation: nightHint 6s ease forwards; }
@keyframes nightHint { 0% { opacity: 0; transform: translateX(-50%) translateY(8px); } 12% { opacity: 1; transform: translateX(-50%) translateY(0); } 80% { opacity: 1; transform: translateX(-50%) translateY(0); } 100% { opacity: 0; transform: translateX(-50%) translateY(-8px); } }

/* Speed gauge moved to the navigation card: bottom right corner of the card. */
.hw-nav .hw-gauge-speed { position: absolute; right: 16px; bottom: 12px; width: 118px; height: 68px; }
.hw-nav .hw-gauge-speed svg { width: 118px; height: 68px; }
.hw-nav .hw-gauge-speed .hw-num { bottom: 4px; }

/* Player: no volume row and no minutes/seconds labels. The progress line stays. */
.player-vol, .player-time { display: none !important; }

/* Clock, weather and player: smaller, and see-through so the wallpaper shows behind them. */
.hero-clock, .weather-widget, .player-widget { height: 140px !important; min-height: 140px !important; }
.hero-clock { flex: 0 0 210px !important; width: 210px !important; min-height: 140px; padding: 16px 20px !important; }
.hero-clock .clock { font-size: clamp(40px, 4vw, 66px); }
.weather-widget { flex-basis: 210px !important; padding: 14px 16px !important; gap: 12px !important; }
.weather-widget .weather-icon { width: 64px; height: 64px; border-radius: 20px; font-size: 34px; }
.player-widget { padding: 12px 20px !important; }
.player-widget .album-art { width: 116px !important; height: 116px !important; border-radius: 22px; }
.hero-clock, .weather-widget, .player-widget { background: rgba(2, 6, 12, .28) !important; backdrop-filter: none !important; }
:root[data-theme="light"] .hero-clock, :root[data-theme="light"] .weather-widget, :root[data-theme="light"] .player-widget { background: rgba(255, 255, 255, .3) !important; }
body.player-expanded .hero-bottom.in-stage > .hero-clock, body.player-expanded .hero-bottom.in-stage > #weather-widget { height: auto !important; }

/* Expanded player: the wallpaper stays inside the top panel only; the page keeps its own background. */
body.player-expanded .dashboard { background: transparent !important; }
body.player-expanded .hero-bottom, body.player-expanded .hero-bottom.in-stage { background: transparent !important; box-shadow: none !important; }


/* Navigation card: the camera block and the speed gauge do not overlap. The gauge is in the right corner, so the turn row keeps clear of it. */
.hw-nav .hw-turn-row { padding-right: 136px; }
.hw-nav .hw-cam { margin-left: 0; }

/* Light theme: values in the state card were pale on white. */
:root[data-theme="light"] .hw-card { color: #13243a; }
:root[data-theme="light"] .hw-chip { border-color: rgba(31, 116, 184, .25); background: rgba(255, 255, 255, .6); }
:root[data-theme="light"] .hw-chip span, :root[data-theme="light"] .hw-cam span, :root[data-theme="light"] .hw-num small { color: #5d7189; }
:root[data-theme="light"] .hw-chip b { color: #13243a; }
:root[data-theme="light"] .hw-chip.open b { color: #1f74b8; }
:root[data-theme="light"] .hw-cam strong { color: #c4661a; }

/* Light theme: the cards' shadow is soft and light, so no dark band shows under the bottom row. */
:root[data-theme="light"] .hero-clock, :root[data-theme="light"] .weather-widget, :root[data-theme="light"] .player-widget { box-shadow: 0 10px 30px rgba(20, 40, 70, .12) !important; }

/* Fan slot in the climate page: ten steps under the title; the lit ones show the level, a tap on a step sets it. */
.action-slot.fan-slot .fan-bar { display: flex; align-items: flex-end; gap: 3px; width: 100%; height: 22px; }
.action-slot.fan-slot .fan-bar i { flex: 1 1 0; min-width: 0; height: 100%; border-radius: 4px; background: var(--line); cursor: pointer; }
.action-slot.fan-slot .fan-bar i.on { background: var(--blue); box-shadow: 0 0 9px rgba(var(--accent-rgb), .55); }
/* Centering of the top cards: car state and compass. The navigation card keeps the reference layout (photo of the car). */
.hw-state, .hw-compass { display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.hw-state .hw-eb, .hw-compass .hw-eb { width: 100%; text-align: center; }
.hw-state .hw-body, .hw-compass .hw-body { width: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.hw-state .hw-chips { width: 100%; justify-content: center; }
.hw-compass .hw-dial { margin: 0 auto; }
.hw-compass .hw-dir { text-align: center; width: 100%; }

/* Expanded player: the wallpaper fills the whole screen behind everything. */
body.player-expanded { background: var(--wallpaper) center / cover no-repeat fixed, #0b0f16 !important; }
body.player-expanded .hero { flex: 1 1 auto; height: auto; margin: 0 !important; width: 100% !important; border: 0 !important; border-radius: 0 !important; box-shadow: none !important; overflow: visible !important; background: none !important; }
body.player-expanded .hero-shade { display: none; }
body.player-expanded .actions-section, body.player-expanded .actions-header { background: transparent !important; }

/* Expanded player: clock, weather and player are frosted glass. */
body.player-expanded .hero-bottom.in-stage > .hero-clock,
body.player-expanded .hero-bottom.in-stage > #weather-widget,
body.player-expanded .hero-bottom.in-stage > .player-widget {
  background: rgba(255, 255, 255, .22) !important;
  backdrop-filter: blur(22px) saturate(1.25) !important;
  -webkit-backdrop-filter: blur(22px) saturate(1.25) !important;
  border: 1px solid rgba(255, 255, 255, .35) !important;
  box-shadow: 0 10px 30px rgba(0, 0, 0, .18) !important;
}
:root[data-theme="dark"] body.player-expanded .hero-bottom.in-stage > .hero-clock,
:root[data-theme="dark"] body.player-expanded .hero-bottom.in-stage > #weather-widget,
:root[data-theme="dark"] body.player-expanded .hero-bottom.in-stage > .player-widget {
  background: rgba(20, 24, 32, .38) !important;
  border-color: rgba(255, 255, 255, .14) !important;
}
html.player-expanded { background: var(--wallpaper) center / cover no-repeat fixed, #0b0f16; }
body.player-expanded .page-controls button { background: rgba(255, 255, 255, .24) !important; backdrop-filter: blur(14px) !important; -webkit-backdrop-filter: blur(14px) !important; border: 1px solid rgba(255, 255, 255, .35) !important; }

/* Slot icons: black in the light theme, white in the dark theme. Pictures (app icons) keep their colours. */
:root[data-theme="light"] .action-slot .action-icon,
:root[data-theme="light"] .action-slot .temp-halves i { color: #000 !important; }
:root[data-theme="dark"] .action-slot .action-icon,
:root[data-theme="dark"] .action-slot .temp-halves i { color: #fff !important; }

/* Level lamps only: heating orange, ventilation light blue. Icons follow the theme. */
.action-slot.warm .level-lamps i.on { background: #ff8a4c; box-shadow: 0 0 11px rgba(255, 138, 76, .8); }
.action-slot.cool .level-lamps i.on { background: #79dcff; box-shadow: 0 0 11px rgba(121, 220, 255, .8); }

/* Navigation: the label and the "На приборку" button are centred across the top of the card (as in the car photo). */
.hw-nav .hw-eb { width: 100%; text-align: center; }
.hw-nav-actions { width: 100%; display: flex; justify-content: center; }

/* Top row: radar, the notice and the track, in one line at the top centre (as in the car photos). */
.hw-status { position: absolute; top: 0; height: 111px; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 4px; z-index: 5; pointer-events: none; white-space: nowrap; }

.hs-cell { display: flex; align-items: center; justify-content: center; height: 30px; padding: 0 14px; border-radius: 999px; border: 1px solid rgba(255, 255, 255, .14); background: rgba(2, 6, 12, .5); font-size: 14px; }
.hs-cell[hidden] { display: none; }
.hs-cam .hw-cam { display: flex; align-items: center; gap: 8px; padding: 0; margin: 0; border: 0; text-align: left; }
.hs-cam .hw-cam::before { content: "Радар · "; font-size: 13px; color: #ff9f43; }
.hs-cam .hw-cam span { font-size: 13px; color: #ff9f43; text-transform: none; letter-spacing: 0; }
.hs-cam .hw-cam strong { font-size: 15px; color: #ff9f43; }
#hs-media-text { max-width: 360px; overflow: hidden; text-overflow: ellipsis; }
#hw-status .toast { position: relative; left: auto; bottom: auto; transform: none; max-width: none; }
#hw-status .toast.visible { transform: none; }
#hw-status .toast:not(.visible) { display: none; }
body.player-expanded .hw-status .hs-cam, body.player-expanded .hw-status .hs-media { display: none; }
/* Light theme: the top row is light, the radar text is dark orange. */
:root[data-theme="light"] .hs-cell { background: rgba(255, 255, 255, .92); border-color: rgba(0, 0, 0, .12); color: #1b2740; }
:root[data-theme="light"] .hs-cam .hw-cam::before, :root[data-theme="light"] .hs-cam .hw-cam span, :root[data-theme="light"] .hs-cam .hw-cam strong { color: #c4661a; }

/* Car state sheet and trips */
.cs-sheet { position: fixed; inset: 0; z-index: 70; display: flex; align-items: center; justify-content: center; background: rgba(0, 0, 0, .45); }
.cs-sheet[hidden], .trips-screen[hidden] { display: none; }
.cs-card { width: min(1000px, 92vw); max-height: 92vh; overflow: auto; padding: 22px 26px; border-radius: 24px; background: #111821; color: #eaf2ff; border: 1px solid rgba(255, 255, 255, .1); }
:root[data-theme="light"] .cs-card { background: #fbfcfe; color: #1b2740; border-color: rgba(0, 0, 0, .1); }
.cs-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.cs-head h2 { margin: 0; font-size: 16px; letter-spacing: .08em; text-transform: uppercase; color: #8aa0bd; font-weight: 600; }
.cs-actions { display: flex; gap: 10px; }
.cs-actions button, .ts-back { border: 1px solid rgba(255, 255, 255, .18); background: transparent; color: inherit; border-radius: 999px; padding: 6px 14px; font: inherit; font-size: 14px; }
.cs-actions .cs-trips { color: #ffd84a; border-color: rgba(255, 216, 74, .6); }
.cs-group { display: grid; grid-template-columns: 1fr 1fr; gap: 0 28px; margin-bottom: 12px; }
.cs-group h4 { grid-column: 1 / -1; margin: 10px 0 4px; font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: #8aa0bd; font-weight: 600; }
.cs-row { display: flex; justify-content: space-between; padding: 9px 0; border-bottom: 1px solid rgba(255, 255, 255, .1); font-size: 15px; }
.cs-row b { font-weight: 600; color: #b9c6d8; }
.cs-row b.open { color: var(--accent); }
.cs-note { font-size: 12px; color: #8aa0bd; margin: 8px 0 0; }
.trips-screen { position: fixed; inset: 0; z-index: 80; background: #0b0f16; color: #eaf2ff; display: flex; flex-direction: column; }
:root[data-theme="light"] .trips-screen { background: #f4f7fb; color: #1b2740; }
.ts-head { display: flex; align-items: center; gap: 14px; padding: 14px 20px; border-bottom: 1px solid rgba(255, 255, 255, .1); }
.ts-head h2 { margin: 0; font-size: 20px; }
.ts-badge { margin-left: auto; padding: 4px 12px; border-radius: 999px; background: #ffd84a; color: #1b2740; font-size: 12px; font-weight: 700; }
.ts-body { flex: 1; display: grid; grid-template-columns: 290px 1fr; min-height: 0; }
.ts-list { overflow: auto; padding: 14px; border-right: 1px solid rgba(255, 255, 255, .1); }
.ts-day { font-size: 11px; letter-spacing: .12em; color: #8aa0bd; margin: 12px 4px 6px; }
.ts-item { display: block; width: 100%; text-align: left; margin-bottom: 8px; padding: 10px 12px; border-radius: 14px; border: 1px solid rgba(255, 255, 255, .12); background: transparent; color: inherit; font: inherit; }
.ts-item.on { border-color: #ffd84a; }
.ts-item strong { display: block; font-size: 15px; }
.ts-item span { display: block; font-size: 12px; color: #8aa0bd; margin-top: 3px; }
.ts-main { overflow: auto; padding: 16px 20px; }
.ts-tiles { display: grid; grid-template-columns: repeat(6, 1fr); gap: 10px; }
.ts-tile { padding: 10px 12px; border-radius: 14px; border: 1px solid rgba(255, 255, 255, .12); }
.ts-tile span { display: block; font-size: 11px; color: #8aa0bd; }
.ts-tile b { display: block; font-size: 17px; margin-top: 4px; }
.ts-tile small { font-size: 11px; color: #8aa0bd; font-weight: 400; }
.ts-chart { margin-top: 14px; padding: 14px; border-radius: 18px; border: 1px solid rgba(255, 255, 255, .12); }
.ts-legend { font-size: 12px; color: #8aa0bd; display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 8px; }
.ts-legend i { display: inline-block; width: 12px; height: 3px; border-radius: 2px; margin-left: 10px; }
.ts-legend i:first-child { margin-left: 0; }
.trip-chart { width: 100%; height: 220px; display: block; }
.trip-axis { display: flex; justify-content: space-between; font-size: 12px; color: #8aa0bd; margin-top: 6px; }

/* Top notices: one column, all the same width and height. */
.hw-status { gap: 4px; }
.hs-cell, #hw-status .toast { width: 360px; height: 32px; box-sizing: border-box; justify-content: center; padding: 0 14px; margin: 0; }
#hw-status .toast { display: flex; align-items: center; justify-content: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 14px; border-radius: 999px; }
#hw-status .toast:not(.visible) { display: none; }
#hs-media-text { max-width: 100%; }

/* Cover mode: the song progress line under the artist stays visible. */
body.player-expanded .player-widget.expanded .track-progress { display: block !important; }

/* Picture icons in slots: black in the light theme, white in the dark theme. Heating and ventilation keep their colours. */
:root[data-theme="light"] .action-slot .action-icon img { filter: brightness(0) !important; }
:root[data-theme="dark"] .action-slot .action-icon img { filter: brightness(0) invert(1) !important; }

/* Нарисованные значки (stage17): размер внутри плитки слота и в списке выбора. Цвет берётся у текста, как у темы. */
.action-icon svg { width: 44px; height: 44px; }
.picker-item-icon svg { width: 34px; height: 34px; }

/* Seat level icons: black in light theme, white in dark, never coloured (only the lamps are). */
:root[data-theme="light"] .action-slot.has-level .action-icon,
:root[data-theme="light"] .action-slot.has-level .action-icon svg { color: #000 !important; }
:root[data-theme="dark"] .action-slot.has-level .action-icon,
:root[data-theme="dark"] .action-slot.has-level .action-icon svg { color: #fff !important; }

/* Wallpaper fills the whole screen behind everything; the top panel stays transparent in cover mode. */
html, body { background: var(--wallpaper) center / cover no-repeat fixed, #0b0f16 !important; }
body .hero { background: none !important; border: 0 !important; }

/* Page tabs: icon before each label. */
.page-tabs .tab-icon { display: inline-flex; width: 18px; height: 18px; margin-right: 6px; vertical-align: middle; }
.page-tabs .tab-icon svg { width: 18px; height: 18px; }
